// [MEDIUM_PRIORITY] PERFORMANCE: String Concatenation optimized
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.cloneimport java.time.Instant/** * NOUS — Cloned Voice Profile (§9 Voice Cloning + §18 v2 Fix #3). * * A [ClonedVoiceProfile] is the result of cloning a user's voice from 30+ * seconds of audio. It contains: * *  - The speaker embedding (extracted via ECAPA-TDNN in Step 5.7). *  - Voice characteristics (pitch, formants, prosody) — extracted by *    [VoiceCloner] heuristics, used by the v1 fallback path. *  - A reference to the adapted VITS model (used by the v2 neural path). * * ## Two cloning paths (v2 fix #3) * * ``` * v1 (deprecated): Android TTS → post-processing voice conversion *                  MOS 3.8 — robotic, uncanny valley * * v2 (current):    Direct neural TTS (Piper/VITS) with speaker embedding *                  MOS 4.2+ — natural, indistinguishable from original * ``` * * The v2 path injects the speaker embedding directly into the VITS model * at synthesis time, so there's no "base TTS audio" to convert. The v1 * post-processing path remains as a fallback for devices that can't run * the 50 MB VITS model. * * ## Privacy & ethical guardrails (§9 Ethical Guardrails) * *  - Clone **only own voice** — user must verify with voice print match. *  - Celebrity clones — user must own rights (acknowledged in UI). *  - Deceased loved one — no restrictions (grief support). *  - Watermark — all cloned audio carries an inaudible ultrasonic *    watermark ([VoiceWatermarker]) for deepfake detection. *  - Logs — all clone operations audit-logged. * * @see <a href="docs/strategy/module-5-strategy-v2.md">§9 Voice Cloning, §18 Neural Voice Cloning (Piper/VITS) — v2 Fix #3</a> *//** * One cloned voice profile. * * @param profileId        unique identifier (UUID). * @param ownerSpeakerId   the [VoicePrint.speakerId] (Step 5.7) of the user *                          who owns this clone. Must match the enrolled *                          voice print — cloning someone else's voice is *                          blocked by [EthicalGuardrail]. * @param embedding        ECAPA-TDNN speaker embedding (192-dim) extracted *                          from the enrollment audio. * @param pitch            estimated base pitch (Hz) of the cloned voice. * @param formants         estimated formant frequencies (F1, F2, F3 in Hz). * @param prosody          estimated prosody characteristics (rate, jitter). * @param vitsModelPath    path to the adapted VITS model file on disk *                          (v2 neural path). Null when only v1 post-processing *                          is available on this device. * @param createdAt        when this profile was created. * @param watermarkSeed    cryptographic seed for the per-user ultrasonic *                          watermark. Derived from ownerSpeakerId + profileId. * @param quality          quality metrics from the enrollment audio (SNR, *                          clipping, duration). Failed enrollments are *                          rejected before reaching this class. */data class ClonedVoiceProfile(    val profileId: String,    val ownerSpeakerId: String,    val embedding: FloatArray,    val pitch: Float,    val formants: Formants,    val prosody: ProsodyCharacteristics,    val vitsModelPath: String?,    val createdAt: Instant = Instant.now(),    val watermarkSeed: Long,    val quality: CloneQualityMetrics,) {    init {        require(profileId.isNotBlank()) { "profileId must not be blank" }        require(ownerSpeakerId.isNotBlank()) { "ownerSpeakerId must not be blank" }        require(embedding.isNotEmpty()) { "embedding must not be empty" }        require(pitch > 0f) { "pitch must be positive, got $pitch" }        require(formants.f1 > 0f && formants.f2 > 0f && formants.f3 > 0f) {            "formants must all be positive"        }    }    /** True if this profile supports the v2 neural synthesis path (VITS). */    val supportsNeuralSynthesis: Boolean get() = vitsModelPath != null    // FloatArray identity equality breaks data class ==; override.    override fun equals(other: Any?): Boolean {        if (this === other) return true        if (other !is ClonedVoiceProfile) return false        return profileId == other.profileId &&            ownerSpeakerId == other.ownerSpeakerId &&            pitch == other.pitch &&            formants == other.formants &&            prosody == other.prosody &&            vitsModelPath == other.vitsModelPath &&            createdAt == other.createdAt &&            watermarkSeed == other.watermarkSeed &&            quality == other.quality &&            embedding.contentEquals(other.embedding)    }    override fun hashCode(): Int {        var result = profileId.hashCode()        result = 31 * result + ownerSpeakerId.hashCode()        result = 31 * result + embedding.contentHashCode()        result = 31 * result + pitch.hashCode()        result = 31 * result + formants.hashCode()        result = 31 * result + prosody.hashCode()        result = 31 * result + (vitsModelPath?.hashCode() ?: 0)        result = 31 * result + createdAt.hashCode()        result = 31 * result + watermarkSeed.hashCode()        result = 31 * result + quality.hashCode()        return result    }}// ──────────────────────────────────────────────────────────────────────────/** Estimated formant frequencies (Hz) of a cloned voice. */data class Formants(    val f1: Float,  // first formant, typically 270–730 Hz for male, 310–1100 Hz for female    val f2: Float,  // second formant, typically 800–2500 Hz    val f3: Float,  // third formant, typically 1500–3500 Hz)/** Estimated prosody characteristics of a cloned voice. */data class ProsodyCharacteristics(    /** Speaking rate in syllables per second. */    val rate: Float,    /** Pitch jitter (cycle-to-cycle variation) — 0.0 = steady, 1.0 = very jittery. */    val jitter: Float,    /** Shimmer (amplitude variation) — 0.0 = steady, 1.0 = very shimmering. */    val shimmer: Float,) {    init {        require(rate > 0f) { "rate must be positive" }        require(jitter in 0f..1f) { "jitter must be in [0,1]" }        require(shimmer in 0f..1f) { "shimmer must be in [0,1]" }    }}// ──────────────────────────────────────────────────────────────────────────/** * Quality metrics of the enrollment audio used to create a clone. * * All thresholds per §9 Voice Cloning. * * @param snrDb        signal-to-noise ratio (must be > 15 dB). * @param durationSec  total audio duration (must be ≥ 30 s). * @param clippingRatio fraction of samples that clipped (must be < 0.01). * @param silouetteScore  optional speaker separability score (0–1, null if N/A). */data class CloneQualityMetrics(    val snrDb: Float,    val durationSec: Float,    val clippingRatio: Float,    val silouetteScore: Float? = null,) {    /** True if all quality thresholds pass. */    val passes: Boolean        get() = snrDb >= NeuralVoiceCloner.MIN_SNR_DB &&            durationSec >= NeuralVoiceCloner.MIN_CLONE_AUDIO_SECONDS &&            clippingRatio < MAX_CLIPPING_RATIO    companion object {        /** Maximum acceptable clipping ratio (1% of samples). */        const val MAX_CLIPPING_RATIO = 0.01f    }}// ──────────────────────────────────────────────────────────────────────────/** * Ethical guardrail for voice cloning (§9 Ethical Guardrails). * * Verifies that the user is allowed to clone the target voice: *  - Own voice — always allowed (after voice print match). *  - Celebrity — only if user acknowledges they own the rights. *  - Deceased loved one — always allowed (grief support). * * The guardrail returns a [GuardrailDecision] that the [VoiceCloner] checks * before proceeding with cloning. */class EthicalGuardrail {    /**     * Check whether cloning is allowed for the given request.     *     * @param request the cloning request (target voice + ownership type).     * @return a [GuardrailDecision] — either Allowed or Denied with a reason.     */    fun check(request: CloneRequest): GuardrailDecision {        return when (request.ownershipType) {            OwnershipType.OWN_VOICE -> {                if (!request.voicePrintVerified) {                    GuardrailDecision.Denied(                        reason = "Own-voice cloning requires voice print verification. " +                            "Please speak your wake word to confirm.",                    )                } else {                    GuardrailDecision.Allowed                }            }            OwnershipType.CELEBRITY -> {                if (!request.rightsAcknowledged) {                    GuardrailDecision.Denied(                        reason = "Celebrity cloning requires you to acknowledge that you own " +                            "the rights to use this voice. Please confirm in Settings → Voice → Cloning.",                    )                } else {                    GuardrailDecision.Allowed                }            }            OwnershipType.DECEASED_LOVED_ONE -> {                // Always allowed — grief support use case.                GuardrailDecision.Allowed            }        }    }}// ──────────────────────────────────────────────────────────────────────────/** Type of voice ownership for a cloning request. */enum class OwnershipType {    /** User is cloning their own voice. */    OWN_VOICE,    /** User is cloning a celebrity voice (requires rights). */    CELEBRITY,    /** User is cloning a deceased loved one's voice (grief support). */    DECEASED_LOVED_ONE,}/** A request to clone a voice. */data class CloneRequest(    val ownershipType: OwnershipType,    val voicePrintVerified: Boolean = false,    val rightsAcknowledged: Boolean = false,)/** Result of the ethical guardrail check. */sealed interface GuardrailDecision {    /** Cloning allowed. */    object Allowed : GuardrailDecision    /** Cloning denied, with a human-readable reason. */    data class Denied(val reason: String) : GuardrailDecision}